    public static CountryInfo GetByIso2(string iso2)
        => _all.First(x => x.Iso2 == iso2);

    public static CountryInfo GetByIso3(string iso3)
        => _all.First(x => x.Iso3 == iso3);

    public static CountryInfo? TryGet(int id)
        => _all.FirstOrDefault(x => x.Id == id);
